import React, { useState, useEffect } from 'react';

function DriverDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('available');
  const [availableDeliveries, setAvailableDeliveries] = useState([]);
  const [activeJobs, setActiveJobs] = useState([]);
  const [history, setHistory] = useState([]);
  const [earnings, setEarnings] = useState({ total: 0, weekly: 0, totalDeliveries: 0, perDelivery: 20 });
  const [loading, setLoading] = useState(true);
  const [isAvailable, setIsAvailable] = useState(true);
  const [selectedJob, setSelectedJob] = useState(null);
  const [socket, setSocket] = useState(null);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchAllData();
    // Simulate real-time updates
    const interval = setInterval(fetchAllData, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      // Fetch available deliveries
      const availRes = await fetch('http://localhost:5000/api/driver/available', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const availData = await availRes.json();
      if (availData.success) setAvailableDeliveries(availData.deliveries);

      // Fetch active jobs
      const jobsRes = await fetch('http://localhost:5000/api/driver/jobs', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const jobsData = await jobsRes.json();
      if (jobsData.success) setActiveJobs(jobsData.jobs);

      // Fetch history
      const historyRes = await fetch('http://localhost:5000/api/driver/history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const historyData = await historyRes.json();
      if (historyData.success) setHistory(historyData.history);

      // Fetch earnings
      const earningsRes = await fetch('http://localhost:5000/api/driver/earnings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const earningsData = await earningsRes.json();
      if (earningsData.success) setEarnings(earningsData.earnings);
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setLoading(false);
    }
  };

  const acceptDelivery = async (deliveryId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/accept/${deliveryId}`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        alert('Delivery accepted!');
        fetchAllData();
      } else {
        alert(data.error || 'Failed to accept');
      }
    } catch (error) {
      alert('Error accepting delivery');
    }
  };

  const updateDeliveryStatus = async (deliveryId, status) => {
    try {
      const res = await fetch(`http://localhost:5000/api/driver/delivery/${deliveryId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        alert(`Delivery marked as ${status}!`);
        fetchAllData();
        setSelectedJob(null);
      }
    } catch (error) {
      alert('Error updating status');
    }
  };

  const getStatusBadge = (status) => {
    const colors = {
      pending: '#f59e0b',
      confirmed: '#10b981',
      'in-progress': '#3b82f6',
      completed: '#8b5cf6',
      cancelled: '#ef4444'
    };
    return { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 12px', borderRadius: '20px', fontSize: '12px' };
  };

  const getDistanceText = () => {
    const distances = ['0.5 miles away', '1.2 miles away', '0.8 miles away', '1.5 miles away'];
    return distances[Math.floor(Math.random() * distances.length)];
  };

  const getEtaText = () => {
    const etas = ['5-10 min', '10-15 min', '8-12 min', '12-18 min'];
    return etas[Math.floor(Math.random() * etas.length)];
  };

  return (
    <div style={styles.dashboard}>
      {/* Header */}
      <div style={styles.header}>
        <div style={styles.logoSection}>
          <span style={styles.logoIcon}>🚗💨</span>
          <h1 style={styles.logoText}>Car Care Connect - Driver</h1>
        </div>
        <div style={styles.userInfo}>
          <span style={styles.statusDot}></span>
          <span>{user.firstName} {user.lastName}</span>
          <button onClick={onLogout} style={styles.logoutButton}>Logout</button>
        </div>
      </div>

      {/* Tabs */}
      <div style={styles.tabs}>
        <button style={{...styles.tab, ...(activeTab === 'available' ? styles.activeTab : {})}} onClick={() => setActiveTab('available')}>
          📦 Available ({availableDeliveries.length})
        </button>
        <button style={{...styles.tab, ...(activeTab === 'active' ? styles.activeTab : {})}} onClick={() => setActiveTab('active')}>
          🚗 Active ({activeJobs.length})
        </button>
        <button style={{...styles.tab, ...(activeTab === 'history' ? styles.activeTab : {})}} onClick={() => setActiveTab('history')}>
          📋 History ({history.length})
        </button>
        <button style={{...styles.tab, ...(activeTab === 'earnings' ? styles.activeTab : {})}} onClick={() => setActiveTab('earnings')}>
          💰 Earnings
        </button>
      </div>

      {/* Content */}
      <div style={styles.content}>
        {loading ? (
          <div style={styles.loading}>Loading deliveries...</div>
        ) : (
          <>
            {/* Available Deliveries Tab */}
            {activeTab === 'available' && (
              <div>
                <div style={styles.statsCard}>
                  <h3>📊 Today's Stats</h3>
                  <p>🟢 You are online and available for pickups</p>
                  <p>💰 Base pay: ${earnings.perDelivery}/delivery + tips</p>
                </div>

                {availableDeliveries.length === 0 ? (
                  <div style={styles.emptyState}>
                    <span style={styles.emptyIcon}>📦</span>
                    <h3>No Available Deliveries</h3>
                    <p>Check back soon for new concierge requests</p>
                  </div>
                ) : (
                  availableDeliveries.map(delivery => (
                    <div key={delivery._id} style={styles.deliveryCard}>
                      <div style={styles.deliveryHeader}>
                        <span style={styles.deliveryType}>🚗 Concierge Pickup</span>
                        <span style={getStatusBadge(delivery.status)}>{delivery.status}</span>
                      </div>

                      <div style={styles.deliveryContent}>
                        <div style={styles.pickupInfo}>
                          <div style={styles.infoIcon}>📍</div>
                          <div>
                            <strong>Pickup Location:</strong>
                            <p>{delivery.pickupAddress || delivery.customerId?.address || 'Customer address'}</p>
                            <span style={styles.distanceBadge}>{getDistanceText()}</span>
                          </div>
                        </div>

                        <div style={styles.arrowIcon}>↓</div>

                        <div style={styles.shopInfo}>
                          <div style={styles.infoIcon}>🔧</div>
                          <div>
                            <strong>Service Center:</strong>
                            <p>{delivery.providerId?.businessName || 'Auto Service Center'}</p>
                            <p>Service: {delivery.serviceName}</p>
                          </div>
                        </div>
                      </div>

                      <div style={styles.deliveryFooter}>
                        <div>
                          <span style={styles.etaBadge}>⏱️ ETA: {getEtaText()}</span>
                          <span style={styles.priceBadge}>💰 ${earnings.perDelivery}</span>
                        </div>
                        <button style={styles.acceptBtn} onClick={() => acceptDelivery(delivery._id)}>
                          Accept Delivery →
                        </button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Active Jobs Tab */}
            {activeTab === 'active' && (
              <div>
                {activeJobs.length === 0 ? (
                  <div style={styles.emptyState}>
                    <span style={styles.emptyIcon}>🚗</span>
                    <h3>No Active Jobs</h3>
                    <p>Accept a delivery to get started</p>
                  </div>
                ) : (
                  activeJobs.map(job => (
                    <div key={job._id} style={styles.activeCard}>
                      <div style={styles.activeHeader}>
                        <span style={styles.activeType}>🚗 Active Delivery</span>
                        <span style={getStatusBadge(job.status)}>{job.status}</span>
                      </div>

                      <div style={styles.progressSteps}>
                        <div style={{...styles.step, ...(job.status === 'confirmed' ? styles.stepActive : styles.stepCompleted)}}>
                          <span>1</span> Pickup
                        </div>
                        <div style={styles.stepLine}></div>
                        <div style={{...styles.step, ...(job.status === 'in-progress' ? styles.stepActive : job.status === 'confirmed' ? {} : styles.stepCompleted)}}>
                          <span>2</span> Drop-off
                        </div>
                        <div style={styles.stepLine}></div>
                        <div style={{...styles.step, ...(job.status === 'completed' ? styles.stepActive : {})}}>
                          <span>3</span> Complete
                        </div>
                      </div>

                      <div style={styles.jobDetails}>
                        <p><strong>Customer:</strong> {job.customerId?.firstName} {job.customerId?.lastName}</p>
                        <p><strong>Phone:</strong> {job.customerId?.phone || 'Not provided'}</p>
                        <p><strong>Service:</strong> {job.serviceName}</p>
                        <p><strong>Shop:</strong> {job.providerId?.businessName}</p>
                      </div>

                      <div style={styles.actionButtons}>
                        {job.status === 'confirmed' && (
                          <button style={styles.pickupBtn} onClick={() => updateDeliveryStatus(job._id, 'in-progress')}>
                            📍 Confirm Pickup
                          </button>
                        )}
                        {job.status === 'in-progress' && (
                          <button style={styles.completeBtn} onClick={() => updateDeliveryStatus(job._id, 'completed')}>
                            ✅ Complete Delivery
                          </button>
                        )}
                        <button style={styles.contactBtn}>📞 Contact Customer</button>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* History Tab */}
            {activeTab === 'history' && (
              <div>
                <h2>📋 Delivery History</h2>
                {history.length === 0 ? (
                  <div style={styles.emptyState}>No completed deliveries yet</div>
                ) : (
                  history.map(delivery => (
                    <div key={delivery._id} style={styles.historyCard}>
                      <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                        <div>
                          <p><strong>{delivery.serviceName}</strong></p>
                          <p>Customer: {delivery.customerId?.firstName} {delivery.customerId?.lastName}</p>
                          <p>📅 {new Date(delivery.bookingDate).toLocaleDateString()}</p>
                        </div>
                        <div style={{ textAlign: 'right' }}>
                          <span style={getStatusBadge(delivery.status)}>{delivery.status}</span>
                          <p style={styles.earningText}>+${earnings.perDelivery}</p>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            )}

            {/* Earnings Tab */}
            {activeTab === 'earnings' && (
              <div>
                <div style={styles.earningsGrid}>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>💰</span>
                    <h3>Total Earnings</h3>
                    <p style={styles.earningsAmount}>${earnings.total}</p>
                  </div>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>📊</span>
                    <h3>This Week</h3>
                    <p style={styles.earningsAmount}>${earnings.weekly}</p>
                  </div>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>🚗</span>
                    <h3>Total Deliveries</h3>
                    <p style={styles.earningsAmount}>{earnings.totalDeliveries}</p>
                  </div>
                  <div style={styles.earningsCard}>
                    <span style={styles.earningsIcon}>⭐</span>
                    <h3>Rating</h3>
                    <p style={styles.earningsAmount}>5.0</p>
                  </div>
                </div>

                <div style={styles.infoCard}>
                  <h3>💡 How It Works</h3>
                  <ul>
                    <li>💰 ${earnings.perDelivery} per delivery + customer tips</li>
                    <li>🕐 Average delivery time: 30-45 minutes</li>
                    <li>📊 Payments processed weekly to your account</li>
                    <li>⭐ Maintain 4.5+ rating for bonus opportunities</li>
                  </ul>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      {/* Quick Stats Bar */}
      <div style={styles.statsBar}>
        <div style={styles.statItem}>
          <span>📦</span>
          <span>Available: {availableDeliveries.length}</span>
        </div>
        <div style={styles.statItem}>
          <span>🚗</span>
          <span>Active: {activeJobs.length}</span>
        </div>
        <div style={styles.statItem}>
          <span>💰</span>
          <span>Today: ${earnings.weekly / 7}</span>
        </div>
      </div>
    </div>
  );
}

